      if (restCode.length) out.push({ id: a.id + '#other', name: '其它', kind: 'sub', path: '', area: a.id, sem: '还没有归入语义分组的源码文件。', kids: restCode.map((p) => fileNode(p, p.slice(a.id.length + 1), a.id)) });
