      const n = { id: a.id, name: a.name, kind: a.group === 'band' ? 'dir' : 'module', path: a.id === ':files' ? '' : a.id, area: a.id, group: a.group,
        owner: a.owner, sem: a.sem, deps: D[a.id] || {}, kids: kids };
      if (a.group === 'band') band.kids.push(n); else root.kids.push(n);
